CREATE TABLE IF NOT EXISTS wallet_users (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallet_ledgers (user_id CHAR(36) PRIMARY KEY, revision BIGINT UNSIGNED NOT NULL DEFAULT 0, state LONGTEXT NULL, updated_at TIMESTAMP(3) NULL, FOREIGN KEY (user_id) REFERENCES wallet_users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallet_sync_requests (user_id CHAR(36) NOT NULL, request_id CHAR(36) NOT NULL, payload_hash CHAR(64) NOT NULL, response LONGTEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(user_id,request_id), FOREIGN KEY(user_id) REFERENCES wallet_users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallet_settings (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB;
